import{_ as l,a0 as p,w as o,s as r,ao as d,I as t,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171212 How to enable Nested Virtualization in KVM on CentOS 7 - RHEL 7","title":"如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化","tag":"201712","desc":""},"relativePath":"201712/20171212 How to enable Nested Virtualization in KVM on CentOS 7 - RHEL 7.md","filePath":"[post].md"}'),c={name:"201712/20171212 How to enable Nested Virtualization in KVM on CentOS 7 - RHEL 7.md"};function h(g,s,k,m,u,b){const n=p("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-centos-7-rhel-7-的-kvm-上启用嵌套虚拟化" tabindex="-1">如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化 <a class="header-anchor" href="#如何在-centos-7-rhel-7-的-kvm-上启用嵌套虚拟化" aria-label="Permalink to “如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化”">​</a></h1><p><strong>嵌套虚拟化</strong>意味着在虚拟机内配置虚拟化环境。换句话说，我们可以说嵌套虚拟化是<ruby>虚拟机管理程序<rt>hypervisor</rt></ruby>的一个特性，它允许我们通过<strong>虚拟化管理程序</strong>（宿主机）的硬件加速在虚拟服务器内安装和运行虚拟机。</p><p>在这篇文章中，我们将讨论如何在 CentOS 7 / RHEL 7 的 KVM 上启用嵌套虚拟化。我假定您已经配置过 KVM 管理程序。如果您不熟悉如何安装和配置 KVM 管理程序，请参考以下文章。</p><h3 id="在-centos-7-x-和-rhel-7-x-安装-kvm-管理程序" tabindex="-1">在 CentOS 7.x 和 RHEL 7.x 安装 KVM 管理程序 <a class="header-anchor" href="#在-centos-7-x-和-rhel-7-x-安装-kvm-管理程序" aria-label="Permalink to “在 CentOS 7.x 和 RHEL 7.x 安装 KVM 管理程序”">​</a></h3><p>让我们进入虚拟化管理程序，验证您的 KVM 宿主机是否启用了嵌套虚拟化。</p><p>基于 Intel 的处理器运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# cat /sys/module/kvm_intel/parameters/nested</span></span>
<span class="line"><span>N</span></span></code></pre></div><p>基于 AMD 的处理器运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# cat /sys/module/kvm_amd/parameters/nested</span></span>
<span class="line"><span>N</span></span></code></pre></div><p>上述命令输出 <code>N</code> 表示嵌套虚拟化是禁用的。如果我们得到的输出是 <code>Y</code> 则表示在您的宿主机已启用嵌套虚拟化。</p><p>现在启用嵌套虚拟化，使用以下内容创建一个文件名为 <code>/etc/modprobe.d/kvm-nested.conf</code> 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# vi /etc/modprobe.d/kvm-nested.conf</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>options kvm-intel nested=1</span></span>
<span class="line"><span>options kvm-intel enable_shadow_vmcs=1</span></span>
<span class="line"><span>options kvm-intel enable_apicv=1</span></span>
<span class="line"><span>options kvm-intel ept=1</span></span></code></pre></div><p>保存并退出文件。</p><p>现在移除 <code>kvm_intel</code> 模块然后通过 <code>modprobe</code> 命令添加同样的模块。在移除模块之前，确保虚拟机已关机，否则我们会得到像 “modprobe: FATAL: Module kvm_intel is in use” 这样的错误信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# modprobe -r kvm_intel</span></span>
<span class="line"><span>[root@kvm-hypervisor ~]# modprobe -a kvm_intel</span></span></code></pre></div><p>现在验证嵌套虚拟化功能是否启用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# cat /sys/module/kvm_intel/parameters/nested</span></span>
<span class="line"><span>Y</span></span></code></pre></div><h3 id="测试嵌套虚拟化" tabindex="-1">测试嵌套虚拟化 <a class="header-anchor" href="#测试嵌套虚拟化" aria-label="Permalink to “测试嵌套虚拟化”">​</a></h3><p>假设我们在 KVM 管理程序上有一台已经启用了嵌套虚拟化的名为 “director” 的虚拟机。在测试之前，确保 CPU 模式为 “host-modle” 或 “host-passthrough” ，使用 Virt-Manager 或 <code>virtsh</code> 编辑命令检查虚拟机的 CPU 模式。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/12/cpu_mode_vm_kvm.jpg" alt="cpu_mode_vm_kvm"></p><p>现在登录 director 这台虚拟机并运行 <code>lscpu</code> 和 <code>lsmod</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# ssh 192.168.126.1 -l root</span></span>
<span class="line"><span>root@192.168.126.1&#39;s password:</span></span>
<span class="line"><span>Last login: Sun Dec 10 07:05:59 2017 from 192.168.126.254</span></span>
<span class="line"><span>[root@director ~]# lsmod | grep kvm</span></span>
<span class="line"><span>kvm_intel             170200  0</span></span>
<span class="line"><span>kvm                   566604  1 kvm_intel</span></span>
<span class="line"><span>irqbypass              13503  1 kvm</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@director ~]# lscpu</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/12/lscpu_command_rhel7_centos7-1024x408.jpg" alt="lscpu_command_rhel7_centos7"></p><p>让我们试着在 director 这台虚拟机的虚拟管理器 GUI 或 <code>virt-install</code> 命令创建一台虚拟机，在我的情况下我使用 <code>virt-install</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@director ~]# virt-install  -n Nested-VM  --description &quot;Test Nested VM&quot;  --os-type=Linux  --os-variant=rhel7  --ram=2048  --vcpus=2  --disk path=/var/lib/libvirt/images/nestedvm.img,bus=virtio,size=10  --graphics none  --location /var/lib/libvirt/images/CentOS-7-x86_64-DVD-1511.iso --extra-args console=ttyS0</span></span>
<span class="line"><span>Starting install...</span></span>
<span class="line"><span>Retrieving file .treeinfo...                                                   | 1.1 kB  00:00:00</span></span>
<span class="line"><span>Retrieving file vmlinuz...                                                     | 4.9 MB  00:00:00</span></span>
<span class="line"><span>Retrieving file initrd.img...                                                  |  37 MB  00:00:00</span></span>
<span class="line"><span>Allocating &#39;nestedvm.img&#39;                                                      |  10 GB  00:00:00</span></span>
<span class="line"><span>Connected to domain Nested-VM</span></span>
<span class="line"><span>Escape character is ^]</span></span>
<span class="line"><span>[    0.000000] Initializing cgroup subsys cpuset</span></span>
<span class="line"><span>[    0.000000] Initializing cgroup subsys cpu</span></span>
<span class="line"><span>[    0.000000] Initializing cgroup subsys cpuacct</span></span>
<span class="line"><span>[    0.000000] Linux version 3.10.0-327.el7.x86_64 (builder@kbuilder.dev.centos.org) (gcc version 4.8.3 20140911 (Red Hat 4.8.3-9) (GCC) ) #1 SMP Thu Nov 19 22:10:57 UTC 2015</span></span>
<span class="line"><span>………………………………………………</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/12/cli-installer-virt-install-command-kvm.jpg" alt="cli-installer-virt-install-command-kvm"></p><p>这证实了嵌套虚拟化已成功启用，因为我们能在虚拟机内创建虚拟机。</p><p>这篇文章到此结束，请分享您的反馈和意见。</p><hr>`,31)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://www.linuxtechi.com/enable-nested-virtualization-kvm-centos-7-rhel-7/"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.linuxtechi.com/enable-nested-virtualization-kvm-centos-7-rhel-7/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),a(n,{href:"https://www.linuxtechi.com"},{default:i(()=>[...s[2]||(s[2]=[e("Pradeep Kumar",-1)])]),_:1}),s[6]||(s[6]=e(" 译者：",-1)),a(n,{href:"https://github.com/zjon"},{default:i(()=>[...s[3]||(s[3]=[e("zjon",-1)])]),_:1}),s[7]||(s[7]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[e("Linux中国",-1)])]),_:1}),s[12]||(s[12]=e(" 荣誉推出",-1))])])}const y=l(c,[["render",h]]);export{C as __pageData,y as default};
